// Generates src/core/bidi_tables.js from the Unicode Character Database:
//   node external/bidi/generate_bidi_tables.mjs [version]
// where version is e.g. 17.0.0 (default: latest).

import fs from "fs";

const version = process.argv[2] || "latest";
const UCD_URL =
  version === "latest"
    ? "https://www.unicode.org/Public/UCD/latest/ucd/"
    : `https://www.unicode.org/Public/${version}/ucd/`;

async function fetchUCD(path) {
  const response = await fetch(UCD_URL + path);
  if (!response.ok) {
    throw new Error(`Cannot fetch ${path}: ${response.status}`);
  }
  const text = await response.text();
  const name = path.split("/").pop().replace(".txt", "");
  const fileVersion = text.match(new RegExp(`^# ${name}-([\\d.]+)\\.txt`))[1];
  const entries = [];
  const defaults = [];
  const missingPrefix = "# @missing:";
  for (const line of text.split("\n")) {
    const isDefault = line.startsWith(missingPrefix);
    const start = isDefault ? missingPrefix.length : 0;
    const data = line.slice(start).split("#", 1)[0].trim();
    if (data) {
      (isDefault ? defaults : entries).push(data.split(";").map(s => s.trim()));
    }
  }
  return { fileVersion, entries, defaults };
}

function formatNumbers(numbers, indent) {
  const hex = n => "0x" + n.toString(16).padStart(4, "0");
  let body = "";
  let line = indent.slice(1);
  for (let i = 0; i < numbers.length; i += 2) {
    const item = ` ${hex(numbers[i])}, ${hex(numbers[i + 1])},`;
    if (line.length + item.length > 80) {
      body += line + "\n";
      line = indent.slice(1);
    }
    line += item;
  }
  return body + line + "\n";
}

// Inclusive [start, end] ranges for each class, L, the default, being first.
function getClassRanges({ entries, defaults }) {
  const aliases = new Map([
    ["Left_To_Right", "L"],
    ["Right_To_Left", "R"],
    ["Arabic_Letter", "AL"],
    ["European_Terminator", "ET"],
  ]);
  const classes = new Array(0x110000).fill("L");
  // Later defaults override earlier defaults. Explicit entries take precedence.
  for (const [range, value] of [...defaults, ...entries]) {
    const [start, end = start] = range.split("..").map(s => parseInt(s, 16));
    const cls = aliases.get(value) ?? value;
    if (cls.length > 3) {
      throw new Error(`Unknown bidi class alias: ${value}`);
    }
    classes.fill(cls, start, end + 1);
  }
  const ranges = new Map([["L", []]]);
  let runStart = 0,
    runClass = classes[0];
  classes.push(null); // Ends the last run.
  for (let cp = 1; cp < classes.length; cp++) {
    const cls = classes[cp];
    if (cls === runClass) {
      continue;
    }
    if (runClass !== "L") {
      let classRanges = ranges.get(runClass);
      if (!classRanges) {
        classRanges = [];
        ranges.set(runClass, classRanges);
      }
      classRanges.push(runStart, cp - 1);
    }
    runStart = cp;
    runClass = cls;
  }
  return ranges;
}

// The mirroring is symmetric, hence keep each pair once.
function getMirroringPairs({ entries }) {
  const mirrors = new Map(
    entries.map(([from, to]) => [parseInt(from, 16), parseInt(to, 16)])
  );
  const pairs = [];
  for (const [from, to] of mirrors) {
    if (mirrors.get(to) !== from) {
      throw new Error(`Asymmetric mirroring: ${from.toString(16)}`);
    }
    if (from < to) {
      pairs.push(from, to);
    }
  }
  return pairs;
}

const derivedBidiClass = await fetchUCD("extracted/DerivedBidiClass.txt");
const bidiMirroring = await fetchUCD("BidiMirroring.txt");
const ucdVersion = derivedBidiClass.fileVersion;
if (bidiMirroring.fileVersion !== ucdVersion) {
  throw new Error("Mismatched UCD versions.");
}

let classRanges = "";
for (const [cls, ranges] of getClassRanges(derivedBidiClass)) {
  classRanges += ranges.length
    ? `  ${cls}: [\n${formatNumbers(ranges, "    ")}  ],\n`
    : `  ${cls}: [],\n`;
}
const mirroringPairs = formatNumbers(getMirroringPairs(bidiMirroring), "  ");

const licenseHeader = fs.readFileSync(
  new URL("../../src/license_header.js", import.meta.url),
  "utf8"
);

const output = `${licenseHeader}
// Generated by external/bidi/generate_bidi_tables.mjs from the Unicode
// Character Database ${ucdVersion}.

// Inclusive [start, end] code point ranges for each bidi class, the first one,
// L, being the default (DerivedBidiClass.txt).
// prettier-ignore
const BidiClassRanges = {
${classRanges}};

// Pairs of mirrored code points (BidiMirroring.txt).
// prettier-ignore
const BidiMirroringPairs = [
${mirroringPairs}];

export { BidiClassRanges, BidiMirroringPairs };
`;

fs.writeFileSync(
  new URL("../../src/core/bidi_tables.js", import.meta.url),
  output
);
